17	package org.springframework.samples.petclinic.rest.controller.v1;
18	
19	import java.time.LocalDate;
20	import java.util.Collection;
21	import java.util.List;
22	import java.util.Locale;
23	import java.util.regex.Pattern;
24	
25	import org.springframework.http.HttpHeaders;
26	import org.springframework.http.HttpStatus;
27	import org.springframework.http.ResponseEntity;
28	import org.springframework.samples.petclinic.mapper.OwnerMapper;
29	import org.springframework.samples.petclinic.mapper.PetMapper;
30	import org.springframework.samples.petclinic.mapper.VisitMapper;
31	import org.springframework.samples.petclinic.model.Owner;
32	import org.springframework.samples.petclinic.model.Pet;
33	import org.springframework.samples.petclinic.model.Visit;
34	import org.springframework.samples.petclinic.rest.api.OwnersApi;
35	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
36	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
37	import org.springframework.samples.petclinic.rest.dto.PetDto;
38	import org.springframework.samples.petclinic.rest.dto.PetFieldsDto;
39	import org.springframework.samples.petclinic.rest.dto.VisitDto;
40	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
41	import org.springframework.samples.petclinic.service.ClinicService;
42	import org.springframework.security.access.prepost.PreAuthorize;
43	import org.springframework.web.bind.annotation.CrossOrigin;
44	import org.springframework.web.bind.annotation.RequestMapping;
45	import org.springframework.web.bind.annotation.RestController;
46	import org.springframework.web.server.ResponseStatusException;
47	import org.springframework.web.util.UriComponentsBuilder;
48	
49	import jakarta.transaction.Transactional;
50	
51	/**
52	 * @author Vitaliy Fedoriv
53	 */
54	
55	@RestController
56	@CrossOrigin(exposedHeaders = "errors, content-type")
57	@RequestMapping("/api")
58	public class OwnerRestControllerV1 implements OwnersApi {
59	
60	    private final ClinicService clinicService;
61	
62	    private final OwnerMapper ownerMapper;
63	
64	    private final PetMapper petMapper;
65	
66	    private final VisitMapper visitMapper;
67	
68	    public OwnerRestControllerV1(ClinicService clinicService,
69	                                 OwnerMapper ownerMapper,
70	                                 PetMapper petMapper,
71	                                 VisitMapper visitMapper) {
72	        this.clinicService = clinicService;
73	        this.ownerMapper = ownerMapper;
74	        this.petMapper = petMapper;
75	        this.visitMapper = visitMapper;
76	    }
77	
78	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
79	    @Override
80	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
81	        Collection<Owner> owners;
82	        if (lastName != null) {
83	            owners = this.clinicService.findOwnerByLastName(lastName);
84	        } else {
85	            owners = this.clinicService.findAllOwners();
86	        }
87	        if (owners.isEmpty()) {
88	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
89	        }
90	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
91	    }
92	
93	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
94	    @Override
95	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
96	        Owner owner = this.clinicService.findOwnerById(ownerId);
97	        if (owner == null) {
98	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
99	        }
100	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
101	    }
102	
103	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
104	    @Override
105	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
106	        HttpHeaders headers = new HttpHeaders();
107	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
108	        String normalizedTelephone = normalizeTelephone(owner.getTelephone());
109	        owner.setTelephone(normalizedTelephone);
110	        owner.setEmail(normalizeEmail(owner.getEmail()));
111	        if (owner.getRegistrationDate() == null) {
112	            owner.setRegistrationDate(LocalDate.now());
113	        }
114	        if (isTelephoneInUse(normalizedTelephone, null)) {
115	            throw new ResponseStatusException(HttpStatus.CONFLICT,
116	                "telephone is already in use by another owner");
117	        }
118	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
119	        if (!sharesHousehold
120	            && this.clinicService.isHouseholdInUse(owner.getLastName(), owner.getAddress(), null)) {
121	            throw new ResponseStatusException(HttpStatus.CONFLICT,
122	                "another owner with the same last name already lives at this address");
123	        }
124	        owner.setCustomerCode(nextCustomerCode(owner.getLastName()));
125	        if (sharesHousehold) {
126	            this.clinicService.assignHousehold(owner);
127	        }
128	        this.clinicService.saveOwner(owner);
129	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
130	        headers.setLocation(UriComponentsBuilder.newInstance()
131	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
132	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
133	    }
134	
135	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
136	    @Override
137	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
138	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
139	        if (currentOwner == null) {
140	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
141	        }
142	        currentOwner.setAddress(ownerFieldsDto.getAddress());
143	        currentOwner.setCity(ownerFieldsDto.getCity());
144	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
145	        currentOwner.setLastName(ownerFieldsDto.getLastName());
146	        currentOwner.setTelephone(normalizeTelephone(ownerFieldsDto.getTelephone()));
147	        currentOwner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
148	        this.clinicService.saveOwner(currentOwner);
149	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
150	    }
151	
152	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
153	    @Transactional
154	    @Override
155	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
156	        Owner owner = this.clinicService.findOwnerById(ownerId);
157	        if (owner == null) {
158	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
159	        }
160	        this.clinicService.deleteOwner(owner);
161	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
162	    }
163	
164	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
165	    @Override
166	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
167	        Owner owner = this.clinicService.findOwnerById(ownerId);
168	        if (owner == null) {
169	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
170	        }
171	        HttpHeaders headers = new HttpHeaders();
172	        Pet pet = petMapper.toPet(petFieldsDto);
173	        owner.setId(ownerId);
174	        pet.setOwner(owner);
175	        pet.getType().setName(null);
176	        this.clinicService.savePet(pet);
177	        PetDto petDto = petMapper.toPetDto(pet);
178	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
179	            .buildAndExpand(pet.getId()).toUri());
180	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
181	    }
182	
183	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
184	    @Override
185	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
186	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
187	        if (currentOwner != null) {
188	            Pet currentPet = this.clinicService.findPetById(petId);
189	            if (currentPet != null) {
190	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
191	                currentPet.setName(petFieldsDto.getName());
192	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
193	                this.clinicService.savePet(currentPet);
194	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
195	            }
196	        }
197	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
198	    }
199	
200	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
201	    @Override
202	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
203	        HttpHeaders headers = new HttpHeaders();
204	        Visit visit = visitMapper.toVisit(visitFieldsDto);
205	        Pet pet = new Pet();
206	        pet.setId(petId);
207	        visit.setPet(pet);
208	        this.clinicService.saveVisit(visit);
209	        VisitDto visitDto = visitMapper.toVisitDto(visit);
210	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
211	            .buildAndExpand(visit.getId()).toUri());
212	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
213	    }
214	
215	
216	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
217	    @Override
218	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
219	        Owner owner = this.clinicService.findOwnerById(ownerId);
220	        if (owner != null) {
221	            Pet pet = owner.getPet(petId);
222	            if (pet != null) {
223	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
224	            }
225	        }
226	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
227	    }
228	
229	    /**
230	     * Builds the customer code for a new owner, formatted {@code '<LAST3>-<NNNN>'} where LAST3 is the
231	     * upper-cased first three letters of the last name and NNNN is a global 4-digit zero-padded
232	     * sequence equal to one more than the current number of owners (e.g. {@code 'SMI-0007'}).
233	     *
234	     * @param lastName the owner's last name
235	     * @return the assigned customer code
236	     */
237	    private String nextCustomerCode(String lastName) {
238	        String prefix = lastName.substring(0, Math.min(3, lastName.length())).toUpperCase(Locale.ROOT);
239	        int sequence = this.clinicService.findAllOwners().size() + 1;
240	        return String.format("%s-%04d", prefix, sequence);
241	    }
242	
243	    /**
244	     * Normalizes a telephone number into E.164 form. Spaces, dashes and brackets are stripped. When
245	     * the value carries a leading {@code '+'} the following country code and digits are kept as-is;
246	     * otherwise country code {@code +61} is assumed and a single leading {@code '0'} is dropped from
247	     * the national digits. The result must be a {@code '+'} followed by 8 to 15 digits. This E.164
248	     * string is what gets stored and returned.
249	     *
250	     * <p>For example {@code "0412 345 678"} is normalized to {@code "+61412345678"}.
251	     *
252	     * @param telephone the raw telephone value supplied by the client
253	     * @return the normalized E.164 telephone number
254	     * @throws ResponseStatusException with {@link HttpStatus#BAD_REQUEST} if the value cannot form a
255	     *                                 valid E.164 number (unexpected characters, or not 8 to 15
256	     *                                 digits after the {@code '+'})
257	     */
258	    private static String normalizeTelephone(String telephone) {
259	        String cleaned = telephone == null ? "" : telephone.replaceAll("[\\s\\-()]", "");
260	        String digits;
261	        if (cleaned.startsWith("+")) {
262	            digits = cleaned.substring(1);
263	        } else {
264	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
265	            digits = "61" + national;
266	        }
267	        if (!digits.matches("[0-9]{8,15}")) {
268	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
269	                "telephone could not be normalized to a valid E.164 number");
270	        }
271	        return "+" + digits;
272	    }
273	
274	    /**
275	     * Returns the E.164 form of an already-stored telephone for duplicate comparison, falling back
276	     * to the raw stored value if it cannot be normalized (e.g. legacy seed data in another format).
277	     *
278	     * @param telephone the stored telephone value, possibly {@code null}
279	     * @return the E.164 form, or the raw value when it cannot be normalized
280	     */
281	    private static String toComparableTelephone(String telephone) {
282	        try {
283	            return normalizeTelephone(telephone);
284	        } catch (ResponseStatusException ex) {
285	            return telephone;
286	        }
287	    }
288	
289	    /**
290	     * Basic syntactic email validation: a non-empty local part, an {@code @}, and a domain
291	     * containing at least one dot, none of the three sections containing whitespace or an
292	     * additional {@code @}.
293	     */
294	    private static final Pattern EMAIL_PATTERN = Pattern.compile("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$");
295	
296	    /**
297	     * Validates and normalizes an optional owner email address. A {@code null} value is left as is
298	     * (email is optional). When a value is supplied it must be a syntactically valid address; the
299	     * value is then stored and returned lower-cased.
300	     *
301	     * @param email the raw email value supplied by the client, possibly {@code null}
302	     * @return the lower-cased email, or {@code null} when none was supplied
303	     * @throws ResponseStatusException with {@link HttpStatus#BAD_REQUEST} if a value is present but
304	     *                                 is not a syntactically valid address
305	     */
306	    private static String normalizeEmail(String email) {
307	        if (email == null) {
308	            return null;
309	        }
310	        if (!EMAIL_PATTERN.matcher(email).matches()) {
311	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
312	                "email must be a syntactically valid address");
313	        }
314	        return email.toLowerCase(Locale.ROOT);
315	    }
316	
317	    /**
318	     * Determines whether the given normalized E.164 telephone is already used by any owner other
319	     * than the one identified by {@code excludeId} (pass {@code null} to consider every owner, e.g.
320	     * on create). Stored telephones are compared by their E.164 value so that differently formatted
321	     * inputs representing the same number are treated as duplicates.
322	     *
323	     * @param normalizedTelephone the already-normalized E.164 telephone to look for
324	     * @param excludeId           id of an owner to ignore during the check, or {@code null} for none
325	     * @return {@code true} if another owner already uses the telephone
326	     */
327	    private boolean isTelephoneInUse(String normalizedTelephone, Integer excludeId) {
328	        for (Owner existing : this.clinicService.findAllOwners()) {
329	            if (excludeId != null && excludeId.equals(existing.getId())) {
330	                continue;
331	            }
332	            if (normalizedTelephone.equals(toComparableTelephone(existing.getTelephone()))) {
333	                return true;
334	            }
335	        }
336	        return false;
337	    }
338	
339	}
